import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.BiFunction;

public class Main {
    public static void main(String[] args) {
        Consumer<String> sapa = nama -> System.out.println("Halo, " + nama);
        Consumer<String> pamit = nama -> System.out.println("Sampai jumpa, " + nama);
        sapa.andThen(pamit).accept("Sari");

        Function<String, Integer> panjang = teks -> teks.length();
        Function<Integer, Integer> kaliSepuluh = n -> n * 10;
        System.out.println(panjang.apply("lambda"));
        System.out.println(panjang.andThen(kaliSepuluh).apply("java"));

        BiFunction<Integer, Integer, String> gabung = (a, b) -> a + " + " + b + " = " + (a + b);
        System.out.println(gabung.apply(2, 3));
    }
}

