import java.util.function.Consumer;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Consumer<String> a = s -> System.out.print(s + "-");
        Consumer<String> b = s -> System.out.print(s.length());
        a.andThen(b).accept("ok");
    }
}

import java.util.function.BiFunction;

public class Main {
    public static void main(String[] args) {
        BiFunction<String, Integer, String> ulang = (s, n) -> {
            String hasil = "";
            for (int i = 0; i < n; i++) {
                hasil = hasil + s;
            }
            return hasil;
        };
        System.out.println(ulang.apply("ha", 3));
    }
}

