cards.solution:
import java.util.function.Consumer;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Function<String, String> teriak = s -> s.toUpperCase() + "!";
        Function<String, Integer> panjang = s -> s.length();
        Consumer<String> cetak = s -> System.out.println(s);
        cetak.accept(teriak.apply("awas"));
        System.out.println(teriak.andThen(panjang).apply("halo"));
    }
}

